                                            if (['light', 'dark', 'ocean'].includes(theme)) {
                                                setSettingStore(prevState => ({
                                                    ...prevState,
                                                    setValue: {
                                                        ...prevState.setValue,
                                                        theme
                                                    }
                                                }));
                                            }
