                                                    if (value == localStorage.getItem('name') || value == '') {
                                                        e.currentTarget.style.transform = 'scale(1) rotate(0deg)'
                                                        element.inert = true
                                                        element.value = 'Invalid'
                                                        element.style.color = '#c32509'
                                                        element.style.border = '3px solid #c32509'
